import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase.js';
import { ShieldCheck, Download, Printer, Share2, Check, AlertCircle } from 'lucide-react';
import { motion } from 'framer-motion';
import QRCode from 'qrcode';

const DARK_LOGO_BASE64 = "data:image/png;base64,";

export default function VerifyCertificate() {
  const { certId } = useParams();
  const [loading, setLoading] = useState(true);
  const [certificate, setCertificate] = useState(null);
  const [error, setError] = useState(null);
  const [qrCodeDataUrl, setQrCodeDataUrl] = useState('');
  const [copied, setCopied] = useState(false);
  const [resolvedUserName, setResolvedUserName] = useState('');

  useEffect(() => {
    async function fetchCertificate() {
      if (!certId) {
        setLoading(false);
        setError('Идентификатор сертификата не указан.');
        return;
      }

      try {
        setLoading(true);
        const certRef = doc(db, 'certificates', certId);
        const snap = await getDoc(certRef);

        if (snap.exists()) {
          const data = { id: snap.id, ...snap.data() };

          // Fetch real course hours from course document if available
          if (data.courseId) {
            try {
              const cSnap = await getDoc(doc(db, 'courses', data.courseId));
              if (cSnap.exists()) {
                const cData = cSnap.data();
                const calcHours = cData.estimatedHours || cData.hours || (Array.isArray(cData.nodes) ? cData.nodes.reduce((acc, n) => acc + (parseFloat(n.hours) || 2), 0) : null);
                if (calcHours) {
                  data.hoursLearned = Math.round(parseFloat(calcHours));
                }
              }
            } catch (e) {
              console.warn('Could not fetch course hours override:', e);
            }
          }

          // Fetch user full name (Имя и Фамилия) from users collection if available
          let name = data.userName || 'Ивакин Даниил';
          if (data.userId) {
            try {
              const uSnap = await getDoc(doc(db, 'users', data.userId));
              if (uSnap.exists()) {
                const uData = uSnap.data();
                const full = uData.fullName || uData.name || (uData.firstName ? `${uData.lastName || ''} ${uData.firstName}`.trim() : null);
                if (full) name = full;
              }
            } catch (e) {
              console.warn('Could not fetch user name override:', e);
            }
          }
          if (name === 'Daniil' || name === 'daniil') {
            name = 'Ивакин Даниил';
          }
          setResolvedUserName(name);

          setCertificate(data);
          
          const verifyUrl = `https://beta.yourwayy.co/verify/${certId}`;
          const qr = await QRCode.toDataURL(verifyUrl, { margin: 1, width: 220 });
          setQrCodeDataUrl(qr);
        } else {
          setError('Сертификат с таким номером не найден в реестре YourWay.');
        }
      } catch (err) {
        console.error('Error fetching certificate:', err);
        setError('Ошибка при проверке подлинности сертификата.');
      } finally {
        setLoading(false);
      }
    }

    fetchCertificate();
  }, [certId]);

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePrint = () => {
    window.print();
  };

  const formatDate = (timestamp) => {
    if (!timestamp) return new Date().toLocaleDateString('ru-RU');
    if (typeof timestamp === 'string') return timestamp;
    if (timestamp.toDate) return timestamp.toDate().toLocaleDateString('ru-RU');
    if (timestamp.seconds) return new Date(timestamp.seconds * 1000).toLocaleDateString('ru-RU');
    return String(timestamp);
  };

  if (loading) {
    return (
      <div className="fixed inset-0 z-[9999] bg-zinc-950 text-white flex flex-col items-center justify-center p-6 font-sans">
        <div className="w-12 h-12 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin mb-4"></div>
        <p className="text-zinc-400 text-sm font-medium font-clash">Загрузка бланка сертификата...</p>
      </div>
    );
  }

  if (error || !certificate) {
    return (
      <div className="fixed inset-0 z-[9999] bg-zinc-950 text-white flex flex-col items-center justify-center p-6 font-sans">
        <div className="max-w-md w-full bg-zinc-900 border border-rose-500/30 rounded-3xl p-8 text-center backdrop-blur-xl shadow-2xl">
          <div className="w-16 h-16 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-full flex items-center justify-center mx-auto mb-4">
            <AlertCircle className="w-8 h-8" />
          </div>
          <h2 className="text-xl font-bold text-white mb-2 font-clash">Сертификат не найден</h2>
          <p className="text-sm text-zinc-400 mb-6">{error || 'Документ с таким номером не существует.'}</p>
          <div className="p-3 bg-zinc-950 rounded-xl text-xs font-mono text-zinc-400 mb-6 border border-zinc-800">
            ID: {certId}
          </div>
          <Link to="/" className="inline-flex items-center justify-center px-6 py-3 bg-zinc-800 hover:bg-zinc-700 text-white rounded-xl text-xs font-bold uppercase tracking-wider transition-all">
            Вернуться на главную
          </Link>
        </div>
      </div>
    );
  }

  const rawCourseName = certificate.courseName || certificate.courseTitle || 'Курс обучения';
  const cleanCourseName = rawCourseName.replace(/^[«"']|[»"']$/g, '').trim();
  const modulesCount = certificate.modulesCount || 12;
  const hoursLearned = certificate.hoursLearned || 40;
  const userLevel = certificate.userLevel || 3;
  const issuedAtDate = formatDate(certificate.issuedAt);

  return (
    <div className="fixed inset-0 z-[9999] overflow-y-auto bg-[#E5E5E5] text-zinc-900 flex flex-col items-center py-8 px-4 font-sans select-none">
      {/* Top Action Header Bar */}
      <motion.div 
        initial={{ opacity: 0, y: -10 }} 
        animate={{ opacity: 1, y: 0 }} 
        className="w-full max-w-[1240px] mb-6 flex flex-wrap items-center justify-between gap-4 bg-zinc-900 text-white p-4 sm:px-6 rounded-2xl shadow-2xl shrink-0"
      >
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 flex items-center justify-center">
            <ShieldCheck className="w-5 h-5" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="text-xs font-bold text-emerald-400 uppercase tracking-wider font-clash">Подлинность подтверждена</span>
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
            </div>
            <p className="text-xs text-zinc-400 font-mono">Реестр YourWay AI &bull; CERTIFICATE No. {certificate.certId || certId}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {certificate.fileUrl && (
            <a
              href={certificate.fileUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs rounded-xl flex items-center gap-2 transition-all shadow-md active:scale-95"
            >
              <Download className="w-4 h-4" />
              <span>Скачать PDF</span>
            </a>
          )}

          <button
            type="button"
            onClick={handlePrint}
            className="p-2.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-xl transition-all"
            title="Распечатать сертификат"
          >
            <Printer className="w-4.5 h-4.5" />
          </button>

          <button
            type="button"
            onClick={handleShare}
            className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-200 font-bold text-xs rounded-xl flex items-center gap-2 transition-all active:scale-95"
          >
            {copied ? <Check className="w-4 h-4 text-emerald-400" /> : <Share2 className="w-4 h-4 text-zinc-400" />}
            <span>{copied ? 'Скопировано!' : 'Поделиться'}</span>
          </button>
        </div>
      </motion.div>

      {/* Main Certificate Sheet Container */}
      <motion.div 
        initial={{ opacity: 0, scale: 0.99 }} 
        animate={{ opacity: 1, scale: 1 }} 
        className="w-full max-w-[1240px] flex justify-center py-2 shrink-0 pb-12"
      >
        {/* Certificate Card replicating reference exactly */}
        <div className="w-full max-w-[1200px] min-h-[820px] bg-white text-black p-10 sm:p-14 rounded-[24px] border-2 border-zinc-900 shadow-2xl flex flex-col justify-between relative font-sans">
          
          {/* Header */}
          <div className="flex items-start justify-between">
            <img src={DARK_LOGO_BASE64} alt="YourWay Logo" className="h-16 sm:h-20 object-contain" />
            <div className="text-sm font-bold font-mono uppercase tracking-wider text-zinc-950 pt-2">
              CERTIFICATE No. {certificate.certId || certId}
            </div>
          </div>

          {/* Center Main Content */}
          <div className="text-center my-8">
            <div className="text-sm font-bold uppercase tracking-[0.25em] text-zinc-400 mb-3 font-sans">
              СЕРТИФИКАТ О ЗАВЕРШЕНИИ КУРСА
            </div>
            <div className="w-16 h-[2.5px] bg-zinc-900 mx-auto mb-6"></div>

            <div className="text-sm font-semibold text-zinc-800 mb-3">
              Этот сертификат вручается
            </div>

            <div className="text-4xl sm:text-5xl font-extrabold text-zinc-950 font-clash mb-4 tracking-tight">
              {resolvedUserName}
            </div>

            <div className="text-sm font-semibold text-zinc-800 mb-3">
              за успешное завершение курса
            </div>

            <div className="text-2xl sm:text-3xl font-extrabold text-zinc-950 max-w-4xl mx-auto mb-5 leading-snug font-clash">
              «{cleanCourseName}»
            </div>

            <div className="text-sm font-semibold text-zinc-400 tracking-wide">
              Пройдено модулей: {modulesCount} &middot; Общее время обучения: {hoursLearned} часа &middot; Уровень: LVL {userLevel}
            </div>
          </div>

          {/* Bottom 3 Columns */}
          <div className="grid grid-cols-3 items-end pb-2 border-t border-zinc-100 pt-6">
            {/* Left */}
            <div className="text-left">
              <div className="text-sm font-bold text-zinc-950 border-b-2 border-zinc-950 inline-block pb-0.5 mb-1.5">
                Методология и сборка:
              </div>
              <div className="text-sm font-bold text-zinc-800">
                AI-assisted (Grok AI)
              </div>
            </div>

            {/* Center QR */}
            <div className="flex flex-col items-center">
              <div className="text-[11px] text-zinc-400 mb-1">qr-code 1</div>
              <div className="w-28 h-28 border border-zinc-950 p-1.5 bg-white">
                {qrCodeDataUrl && <img src={qrCodeDataUrl} alt="QR Code" className="w-full h-full object-contain" />}
              </div>
              <div className="text-xs font-semibold text-zinc-400 mt-1.5">Проверка подлинности</div>
            </div>

            {/* Right Date */}
            <div className="text-right">
              <div className="text-sm font-bold text-zinc-950 border-b-2 border-zinc-950 inline-block pb-0.5 mb-1.5">
                {issuedAtDate}
              </div>
              <div className="text-sm font-semibold text-zinc-400">Дата выдачи</div>
            </div>
          </div>

          {/* Footer Credits */}
          <div className="flex justify-between items-center text-xs font-bold text-zinc-400 pt-3 border-t border-zinc-100">
            <div>Powered by Grok AI</div>
            <div>Created by Ivakin Daniil</div>
          </div>
        </div>
      </motion.div>
    </div>
  );
}
